create type public.app_role as enum ('employee','supervisor','admin');
create type public.timecard_status as enum ('draft','submitted','returned','approved','amended');
create table public.organizations(id uuid primary key default gen_random_uuid(),name text not null,timezone text not null default 'America/Los_Angeles',created_at timestamptz not null default now());
create table public.profiles(id uuid primary key references auth.users(id),organization_id uuid not null references public.organizations(id),display_name text not null,role app_role not null default 'employee',active boolean not null default true,created_at timestamptz not null default now());
create table public.organization_settings(organization_id uuid primary key references public.organizations(id),week_starts_on smallint not null default 0 check(week_starts_on between 0 and 6),overtime_after_hours numeric(5,2) not null default 40,meal_required_after_hours numeric(5,2) not null default 6,meal_minimum_minutes integer not null default 30,certification_text text not null,certification_version text not null default '1');
create table public.supervisor_assignments(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),employee_id uuid not null references public.profiles(id),supervisor_id uuid not null references public.profiles(id),active boolean not null default true,unique(employee_id,supervisor_id));
create table public.monthly_timecards(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),employee_id uuid not null references public.profiles(id),month date not null,status timecard_status not null default 'draft',current_version integer not null default 1,created_at timestamptz not null default now(),unique(employee_id,month));
create table public.time_entries(id uuid primary key default gen_random_uuid(),timecard_id uuid not null references public.monthly_timecards(id),employee_id uuid not null references public.profiles(id),work_date date not null,start_time time,lunch_start time,lunch_end time,end_time time,start_kind text not null default 'actual' check(start_kind in('actual','anticipated')),end_kind text not null default 'actual' check(end_kind in('actual','anticipated')),paid_minutes integer check(paid_minutes>=0),notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(employee_id,work_date));
create table public.timecard_versions(id uuid primary key default gen_random_uuid(),timecard_id uuid not null references public.monthly_timecards(id),version integer not null,snapshot jsonb not null,locked_at timestamptz,created_at timestamptz not null default now(),unique(timecard_id,version));
create table public.employee_certifications(id uuid primary key default gen_random_uuid(),timecard_version_id uuid not null unique references public.timecard_versions(id),employee_id uuid not null references public.profiles(id),display_name text not null,typed_signature text not null,certification_text text not null,certification_version text not null,signed_at timestamptz not null default now());
create table public.supervisor_approvals(id uuid primary key default gen_random_uuid(),timecard_version_id uuid not null unique references public.timecard_versions(id),supervisor_id uuid not null references public.profiles(id),typed_signature text not null,affirmation text not null,approved_at timestamptz not null default now());
create table public.amendments(id uuid primary key default gen_random_uuid(),timecard_version_id uuid not null references public.timecard_versions(id),requested_by uuid not null references public.profiles(id),original_value jsonb not null,corrected_value jsonb not null,difference_minutes integer not null,reason text not null,status text not null default 'pending',created_at timestamptz not null default now());
create table public.audit_events(id bigint generated always as identity primary key,organization_id uuid not null references public.organizations(id),actor_id uuid references public.profiles(id),subject_id uuid,action text not null,before_value jsonb,after_value jsonb,created_at timestamptz not null default now());
create table public.notification_events(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),recipient_id uuid not null references public.profiles(id),kind text not null,period text not null,status text not null,provider_id text,created_at timestamptz not null default now(),unique(recipient_id,kind,period));
create index on public.time_entries(timecard_id,work_date);create index on public.monthly_timecards(organization_id,month,status);create index on public.audit_events(organization_id,created_at desc);
alter table public.profiles enable row level security;alter table public.time_entries enable row level security;alter table public.monthly_timecards enable row level security;alter table public.timecard_versions enable row level security;
create function public.current_role() returns app_role language sql stable security definer set search_path=public as $$select role from profiles where id=auth.uid() and active$$;
create policy profiles_self_or_admin on public.profiles for select using(id=auth.uid() or (organization_id=(select organization_id from profiles where id=auth.uid()) and current_role()='admin'));
create policy entries_employee_read on public.time_entries for select using(employee_id=auth.uid() or current_role()='admin' or exists(select 1 from supervisor_assignments s where s.employee_id=time_entries.employee_id and s.supervisor_id=auth.uid() and s.active));
create policy entries_employee_write on public.time_entries for all using(employee_id=auth.uid() and not exists(select 1 from monthly_timecards m where m.id=timecard_id and m.status='approved')) with check(employee_id=auth.uid());
create policy cards_authorized_read on public.monthly_timecards for select using(employee_id=auth.uid() or current_role()='admin' or exists(select 1 from supervisor_assignments s where s.employee_id=monthly_timecards.employee_id and s.supervisor_id=auth.uid() and s.active));
create policy versions_authorized_read on public.timecard_versions for select using(exists(select 1 from monthly_timecards m where m.id=timecard_id and (m.employee_id=auth.uid() or current_role()='admin' or exists(select 1 from supervisor_assignments s where s.employee_id=m.employee_id and s.supervisor_id=auth.uid() and s.active))));
